___CSS_LOADER_EXPORT___.push([module.id, `.container {
  background-color: #f5f5f5;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 400px;
  height: 400px;
  border-radius: 50%;
  position: relative;
  overflow: hidden;
}

.loading-icon {
  width: 70%;
  height: 70%;
  position: relative;
  z-index: 3;
  animation: convertToWhite 7s ease-out forwards;
}

.loading-right,
.loading-left {
  position: absolute;
  width: 1000px;
  height: 1000px;
  top: 100%;
  animation-fill-mode: forwards;
  animation-duration: 7s;
  animation-timing-function: ease-out;
}

.loading-right {
  left: calc(50% - 400px * 2.5 / 2);
  z-index: 2;
  animation-name: moveUpRight;
}

.loading-left {
  left: calc(50% - 400px * 2.5 / 2);
  z-index: 1;
  animation-name: moveUpLeft;
}

@keyframes convertToWhite {
  0% {
    filter: invert(100%);
  }
  100% {
    filter: invert(0%);
  }
}
@keyframes moveUpRight {
  0% {
    transform: translate(-25%, 0%);
  }
  100% {
    transform: translate(25%, -50%);
  }
}
@keyframes moveUpLeft {
  0% {
    transform: translate(25%, 0%);
  }
  100% {
    transform: translate(-25%, -50%);
  }
}`, ""]);
